sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var body = request.body.data;
    var sessionId = (body && body.session_id) ? body.session_id + '' : 'default';
    var prompt = (body && body.prompt) ? body.prompt + '' : '';
    var model = (body && body.model) ? body.model + '' : '';
    var systemPrompt = (body && body.system_prompt) ? body.system_prompt + '' : '';
    var prefill = (body && body.prefill) ? body.prefill + '' : '';
    var stopSeqsRaw = (body && body.stop_sequences) ? body.stop_sequences + '' : '';

    if (!prompt) {
        response.setStatus(400);
        response.setBody({ error: 'prompt is required' });
        return;
    }

    // Get existing conversation history from session
    var historyKey = 'claude_history_' + sessionId;
    var historyStr = gs.getSession().getClientData(historyKey) || '[]';
    var messages;
    try {
        messages = JSON.parse(historyStr);
    } catch (e) {
        messages = [];
    }

    // Add user message
    messages.push({ role: 'user', content: prompt });

    // Parse stop sequences (comma-separated string)
    var stopArr = [];
    if (stopSeqsRaw) {
        var parts = (stopSeqsRaw).split(',');
        for (var i = 0; i < parts.length; i++) {
            var s = parts[i].trim();
            if (s) { stopArr.push(s); }
        }
    }

    // Call Claude via the ClaudeConnector script include
    var connector = new x_146833_claudec_0.ClaudeConnector();
    var result = connector.chat(messages, {
        model: model,
        system_prompt: systemPrompt,
        prefill: prefill,
        stop_sequences: stopArr
    });

    if (result.success) {
        // Add assistant reply to conversation history
        messages.push({ role: 'assistant', content: result.text });
        gs.getSession().putClientData(historyKey, JSON.stringify(messages));

        response.setBody({
            text: result.text,
            model: result.model,
            inputTokens: result.inputTokens,
            outputTokens: result.outputTokens,
            totalTokens: (result.inputTokens || 0) + (result.outputTokens || 0)
        });
    } else {
        response.setStatus(500);
        response.setBody({ error: result.error || 'Unknown error' });
    }
})(request, response);
